from taf.ul.ettf.utils.exception import LibraryError
from taf.ul.ettf.utils import exception_causes
from collections import namedtuple


CapturingParams = namedtuple('CapturingParams', ['capturing_filter', 'interfaces'])


class CapturingFilter(object):
    MAIN_FILTER = ''
    INTERFACE = ''

    def __init__(self, capturing_filter=''):
        self.capturing_filter = capturing_filter

    @property
    def filters(self):
        capturing_filter_part = ' and {}'.format(self.capturing_filter) if self.capturing_filter else self.capturing_filter
        return self.MAIN_FILTER + capturing_filter_part


class RRC(CapturingFilter):
    MAIN_FILTER = 'lte_rrc'
    INTERFACE = 'eth4'


class S1AP(CapturingFilter):
    MAIN_FILTER = 's1ap'
    INTERFACE = 'eth3'


class X2AP(CapturingFilter):
    MAIN_FILTER = 'x2ap'
    INTERFACE = 'eth3'


class X2AP_MULTIENB(CapturingFilter):
    MAIN_FILTER = 'x2ap'
    INTERFACE = 'eth5'


class LOOPBACK(CapturingFilter):
    INTERFACE = 'lo'


class FilterBuilderError(LibraryError):
    pass


class FilterBuilder(object):
    def __init__(self):
        self.capturing_filters = []

    def _append(self, capturing_filter):
        self.capturing_filters.append(capturing_filter)

    def with_rrc_ue_messages(self, *ue_ids):
        return self._with_rrc('ue_id', ue_ids)

    def with_rrc_cell_messages(self, *cell_ids):
        return self._with_rrc('cell_id', cell_ids)

    def with_rrc_enb_messages(self, *enb_ids):
        return self._with_rrc('enb_id', enb_ids)

    def _with_rrc(self, filter_name, ids):
        if not ids:
            self._append(RRC('iphy.{}'.format(filter_name)))
            return self

        filters = ['iphy.{}=={}'.format(filter_name, object_id) for object_id in ids]
        self._append(RRC('({})'.format(' or '.join(filters))))
        return self

    def with_s1_messages(self):
        self._append(S1AP())
        return self

    def with_x2_messages(self):
        self._append(X2AP())
        return self

    def with_multienb_x2_messages(self):
        self._append(X2AP_MULTIENB())
        return self.with_x2_messages()

    def with_loopback_messages(self):
        self._append(LOOPBACK())
        return self

    def build(self):
        filters = ' or '.join(sorted({'({})'.format(f.filters) for f in self.capturing_filters if f.filters}))
        interfaces = sorted({capturing_filter.INTERFACE for capturing_filter in self.capturing_filters})

        if not filters and not interfaces:
            raise FilterBuilderError(cause=exception_causes.EMPTY_CONTAINER, message='Capturing filter and interfaces list are empty')

        return CapturingParams(filters, interfaces)
